package com.soulsync.domain;
import jakarta.persistence.*; import lombok.*; import java.time.Instant; import java.util.UUID; import com.soulsync.domain.Enums.ReportStatus;
@Entity @Table(name="reports") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Report { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="reporter_id",nullable=false) private User reporter; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="reported_id",nullable=false) private User reported; @Column(nullable=false) private String reason; @Column(length=2000) private String details; @Enumerated(EnumType.STRING) @Column(nullable=false) @Builder.Default private ReportStatus status=ReportStatus.OPEN; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @PrePersist void pre(){var n=Instant.now();if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=n;updatedAt=n;} @PreUpdate void up(){updatedAt=Instant.now();} }
